  --danger-bg-hover: #d34255;
  --focus: #9ec1ff;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.55);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: radial-gradient(
      1200px 600px at 80% -10%,
      rgba(138, 166, 255, 0.08),
      transparent 60%
    ),
    var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -40px;
  background: var(--bg-elev-2);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  border: 1px solid var(--border-strong);
  z-index: 100;
  transition: top 0.15s;
}
.skip-link:focus {
  top: 0.5rem;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: rgba(20, 23, 31, 0.7);
  backdrop-filter: blur(8px);
}
.brand {
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
}
.nav-list {
  display: flex;
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav-list a {
  color: var(--text-muted);
  font-size: 0.95rem;
}
.nav-list a:hover {
  color: var(--text);
}

/* Preview */
main {
  display: flex;
  justify-content: center;
  padding: 2rem 1.25rem 4rem;
}
.preview {
  width: 100%;
  max-width: 880px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.75rem;
  box-shadow: var(--shadow);
}
.preview__crumbs {
  margin: 0 0 0.5rem;
  font-size: 0.875rem;
  color: var(--text-muted);
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.preview__crumbs span {
  color: var(--border-strong);
}
.preview h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}
.preview__meta {
  margin: 0 0 1.25rem;
  color: var(--text-muted);
  font-size: 0.875rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.preview__meta span[aria-hidden] {
  color: var(--border-strong);
}

.preview__figure {
  margin: 0 0 1.25rem;
  border-radius: 10px;
  overflow: hidden;
  background: #000;
  border: 1px solid var(--border);
}
.preview__image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 60vh;
  object-fit: cover;
}
.preview__caption {
  padding: 0.75rem 1rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  background: var(--bg-elev-2);
  border-top: 1px solid var(--border);
}

.preview__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
  justify-content: flex-end;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font: inherit;
  font-weight: 500;
  font-size: 0.95rem;
  padding: 0.625rem 1.1rem;
  min-height: 44px;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s,
    transform 0.05s;
}
.btn:active {
  transform: translateY(1px);
}
.btn__icon {
  flex: none;
}

.btn--ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn--ghost:hover {
  background: var(--bg-elev-2);
  border-color: #4a5170;
}

.btn--danger {
  background: var(--danger-bg);
  color: #fff;
  border-color: transparent;
}
.btn--danger:hover {
  background: var(--danger-bg-hover);
}

/* Dialog */
.dialog {
  padding: 0;
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  background: var(--bg-elev);
  color: var(--text);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  box-shadow: var(--shadow);
}
.dialog::backdrop {
  background: rgba(4, 6, 12, 0.65);
  backdrop-filter: blur(3px);
}

/* Closed state: ensure no layout / focus when not open */
.dialog:not([open]) {
  display: none;
}

.dialog__inner {
  padding: 1.5rem;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.dialog__title {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.dialog__body {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog__body strong {
  color: var(--text);
  font-weight: 600;
}
.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
}

/* Live status toast */
.status {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 0.6rem 1.1rem;
  font-size: 0.9rem;
  box-shadow: var(--shadow);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}
.status.is-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

/* Forced colors / Windows high contrast */
@media (forced-colors: active) {
  .btn {
    border: 1px solid ButtonBorder;
  }
  .btn--danger {
    background: ButtonFace;
    color: ButtonText;
  }
  .dialog {
    border: 1px solid CanvasText;
  }
  :focus-visible {
    outline: 2px solid Highlight;
  }
}
