  margin: 0 0 0.5rem;
  font-size: 0.875rem;
  color: var(--text-muted);
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.preview__crumbs span {
  color: var(--border-strong);
}
.preview h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}
.preview__meta {
  margin: 0 0 1.25rem;
